<?php
require_once __DIR__ . '/auth.php';
admin_require_role(['superadmin','admin','analyst']);
require_once __DIR__ . '/_layout.php';
require_once __DIR__ . '/../config/database.php';
$totalUsers = admin_query_value($conn, "SELECT COUNT(*) value FROM users");
$activeUsers = admin_query_value($conn, "SELECT COUNT(*) value FROM users WHERE is_active=1");
$tasks = admin_query_value($conn, "SELECT COUNT(*) value FROM tasks");
$completed = admin_query_value($conn, "SELECT COUNT(*) value FROM tasks WHERE status='Completed'");
$checkins = admin_query_value($conn, "SELECT COUNT(*) value FROM procrastiblock_logs WHERE log_type='checkin'");
$completionRate = $tasks ? round($completed / $tasks * 100) : 0;
$levels = mysqli_query($conn, "SELECT CASE ut.tendency_level WHEN 'very_low' THEN 'Few Delay Signals' WHEN 'low' THEN 'Occasional Delay Signals' WHEN 'moderate' THEN 'Some Delay Signals' WHEN 'high' THEN 'Frequent Delay Signals' WHEN 'very_high' THEN 'Elevated Delay Signals' ELSE 'Unclassified' END level, COUNT(*) total FROM users u LEFT JOIN user_tendency ut ON ut.id=(SELECT latest.id FROM user_tendency latest WHERE latest.user_id=u.id ORDER BY latest.classified_at DESC,latest.id DESC LIMIT 1) WHERE u.is_active=1 GROUP BY level ORDER BY total DESC");
$weekly = [];
for ($i = 5; $i >= 0; $i--) {
    $start = date('Y-m-d', strtotime('-' . ($i * 7 + 6) . ' days'));
    $end = date('Y-m-d', strtotime('-' . ($i * 7) . ' days'));
    $weekly[] = ['label' => date('M j', strtotime($start)), 'end_label' => date('M j, Y', strtotime($end)), 'count' => (int)admin_query_value($conn, "SELECT COUNT(*) value FROM tasks WHERE status='Completed' AND DATE(completed_at) BETWEEN '$start' AND '$end'")];
}
admin_page_start('Overview', 'dashboard');
?><section class="workspace-welcome"><div><p class="eyebrow">THE BIG PICTURE</p><h2>Small steps. Meaningful progress.</h2><p>Your student community, in one place. Explore activity, understand patterns, and find opportunities to offer support.</p></div><a class="button primary" href="reports.php">Explore reports &rarr;</a></section><section class="grid stats"><article class="card"><div class="stat-label">Students</div><div class="stat-value"><?php echo $totalUsers; ?></div><div class="stat-meta"><?php echo $activeUsers; ?> active accounts</div></article><article class="card"><div class="stat-label">Tasks tracked</div><div class="stat-value"><?php echo $tasks; ?></div><div class="stat-meta">Across all student accounts</div></article><article class="card"><div class="stat-label">Completion rate</div><div class="stat-value"><?php echo $completionRate; ?>%</div><div class="stat-meta"><?php echo $completed; ?> completed tasks</div></article><article class="card"><div class="stat-label">Check-ins</div><div class="stat-value"><?php echo $checkins; ?></div><div class="stat-meta">Behavior signals collected</div></article></section><section class="grid two"><article class="card"><div class="card-title"><h2>Completion trend</h2><span class="muted">Last 6 weeks</span></div><?php include __DIR__.'/_completion_chart.php'; ?></article><article class="card"><div class="card-title"><h2>Risk distribution</h2><span class="muted">Anonymized</span></div><?php if ($levels && mysqli_num_rows($levels)): while ($level = mysqli_fetch_assoc($levels)): $pct = $totalUsers ? round($level['total'] / $totalUsers * 100) : 0; ?><div class="bar-row"><span><?php echo htmlspecialchars($level['level']); ?></span><div class="bar"><i style="width:<?php echo $pct; ?>%"></i></div><strong><?php echo $level['total']; ?></strong></div><?php endwhile; else: ?><p class="muted">No classifications available yet.</p><?php endif; ?></article></section><section class="grid two"><article class="card"><div class="card-title"><h2>Support signal</h2><span class="badge good">Privacy-first</span></div><p class="muted">Use aggregate trends to identify where support may be needed. Individual student details are intentionally kept out of this overview.</p><a class="button secondary" href="reports.php">Open reports →</a></article><article class="card"><div class="card-title"><h2>Quick actions</h2></div><div class="toolbar"><a class="button primary" href="users.php">Manage users</a><a class="button secondary" href="exports.php">Export summary</a></div></article></section><?php admin_page_end(); ?>
